<?php require_once __DIR__ . '/../src/partials.php';$pdo=db();$stats=$pdo->query("SELECT COUNT(*) products,COALESCE(SUM(current_stock),0) stock,COUNT(*) FILTER(WHERE current_stock<=min_stock) low FROM products WHERE active=TRUE")->fetch();$month=(int)date('m');$year=(int)date('Y');$out=$pdo->prepare("SELECT COALESCE(SUM(quantity),0) FROM stock_movements WHERE movement_type='OUT' AND EXTRACT(MONTH FROM created_at)=? AND EXTRACT(YEAR FROM created_at)=?");$out->execute([$month,$year]);$outQty=$out->fetchColumn();$rows=$pdo->query("SELECT TO_CHAR(months.month,'YYYY-MM') label,COALESCE(SUM(m.quantity),0) qty FROM generate_series(date_trunc('month',CURRENT_DATE)-interval '11 months',date_trunc('month',CURRENT_DATE),interval '1 month') months(month) LEFT JOIN stock_movements m ON m.movement_type='OUT' AND date_trunc('month',m.created_at)=months.month GROUP BY months.month ORDER BY months.month")->fetchAll();$top=$pdo->query("SELECT p.name,SUM(m.quantity) qty FROM stock_movements m JOIN products p ON p.id=m.product_id WHERE m.movement_type='OUT' AND m.created_at>=date_trunc('month',CURRENT_DATE)-interval '5 months' GROUP BY p.id,p.name ORDER BY qty DESC LIMIT 8")->fetchAll();page_start('แดชบอร์ด');?>
