<?php $lowRows=$pdo->query("SELECT name,current_stock,min_stock FROM products WHERE current_stock<=min_stock ORDER BY current_stock ASC,name ASC LIMIT 6")->fetchAll(); if(!$lowRows): ?><div class="health-empty">✓ สต๊อกอยู่ในระดับปกติ</div><?php else: foreach($lowRows as $lr): $min=max(1,(int)$lr['min_stock']); $pct=min(100,round(((int)$lr['current_stock']/$min)*100)); ?><div class="health-row"><div style="min-width:0;flex:1"><div class="health-name"><?=h($lr['name'])?></div><div class="progress-track"><div class="progress-bar" style="width:<?=$pct?>%;background:linear-gradient(90deg,#ef4444,#f59e0b)"></div></div></div><div class="health-stock"><?=number_format($lr['current_stock'])?> / <?=number_format($lr['min_stock'])?></div></div><?php endforeach; endif; ?></div></div>
