<script src="https://cdn.jsdelivr.net/npm/chart.js"></script><script>const monthly=<?=json_encode($rows,JSON_UNESCAPED_UNICODE)?>;const top=<?=json_encode($top,JSON_UNESCAPED_UNICODE)?>;new Chart(document.getElementById('monthlyChart'),{type:'line',data:{labels:monthly.map(x=>x.label),datasets:[{label:'จำนวนเบิก',data:monthly.map(x=>Number(x.qty)),tension:.35,fill:true,borderColor:'#4f46e5',backgroundColor:'rgba(79,70,229,.10)',pointBackgroundColor:'#4f46e5',pointRadius:3}]},options:{responsive:true,plugins:{legend:{display:false}},scales:{y:{beginAtZero:true,grid:{color:'rgba(148,163,184,.16)'}},x:{grid:{display:false}}}}});new Chart(document.getElementById('topChart'),{type:'bar',data:{labels:top.map(x=>x.name),datasets:[{label:'จำนวนเบิก',data:top.map(x=>Number(x.qty)),backgroundColor:['#4f46e5','#2563eb','#0891b2','#10b981','#f59e0b','#f97316','#ec4899','#7c3aed'],borderRadius:8,barThickness:20}]},options:{responsive:true,indexAxis:'y',plugins:{legend:{display:false}},scales:{x:{beginAtZero:true,grid:{color:'rgba(148,163,184,.16)'}},y:{grid:{display:false}}}}});</script><?php page_end();
